from __future__ import annotations

__doc__ = """Symbolic scalar modifiers used by the quantum-operator helpers."""

from ...aux import configured_zero_tol

ZEROTOL = configured_zero_tol()


def autoconvert(func):
    """
    Convert the args of a two-input function into instances of cls
    """

    def wrapper(cls, first, second=None):
        if not isinstance(first, cls):
            first = cls(first)
        if second is not None:
            if not isinstance(second, cls):
                second = cls(second)
            return func(cls, first, second)
        return func(cls, first)

    return wrapper


class _Modifier:
    """Modifier parent class to make sure all that is needed is defined"""

    def __init__(self, value, **_kwargs):
        assert not isinstance(value, _Modifier)
        self._val = value

    @classmethod
    def to_modifier(cls, value, default=None) -> _Modifier:
        """guarantee that the value has the right modifier."""
        if value is None:
            if default is None:
                return cls.identity()
            assert isinstance(default, _Modifier)
            value = default.copy()
        if isinstance(value, cls):
            return value
        if isinstance(value, _Modifier):
            raise TypeError("Wrong modifier type")
        return cls(value)

    def copy(self) -> _Modifier:
        """return a copy of the current scalar"""
        return self.__class__(self._val)

    def to_complex_components(self) -> tuple:
        """split into complex components"""
        raise NotImplementedError(
            "'to_complex_components' must be defined by subclass."
        )

    def to_str(self, **_kwargs):
        """
        Default string conversion.
        """
        return str(self.value)

    @classmethod
    def identity(cls):
        """identity, neutral element of multiplication"""
        return cls(1)

    @classmethod
    def zero(cls):
        """zero, neutral element of addition"""
        return cls(0)

    @classmethod
    def from_product(cls, *factors):
        """generate from a product"""
        ret = cls.identity()
        for val in factors:
            if isinstance(val, _Modifier):
                ret *= val
            else:
                ret *= cls(val)
        return ret

    @property
    def value(self):
        """value property"""
        return self._val * 1

    @property
    def real(self):
        """value property"""
        real, _ = self.to_complex_components()
        return real

    @property
    def imag(self):
        """value property"""
        _, imag = self.to_complex_components()
        return imag

    # class handler for arithmetics
    # -----------------------------

    @classmethod
    @autoconvert
    def _add(cls, first, second) -> _Modifier:
        return cls(first.value + second.value)

    @classmethod
    @autoconvert
    def _sub(cls, first, second) -> _Modifier:
        return cls(first.value - second.value)

    @classmethod
    @autoconvert
    def _mul(cls, first, second) -> _Modifier:
        return cls(first.value * second.value)

    @classmethod
    @autoconvert
    def _div(cls, first, second) -> _Modifier:
        return cls(first.value / second.value)

    @classmethod
    @autoconvert
    def _pow(cls, first, second) -> _Modifier:
        return cls(first.value**second.value)

    @classmethod
    @autoconvert
    def _abs(cls, first) -> float:
        return abs(first.value)

    # forward dunder methods into class handlers
    # ------------------------------------------

    def __add__(self, other):
        return self.__class__._add(self, other)

    def __radd__(self, other):
        return self.__class__._add(other, self)

    def __sub__(self, other):
        return self.__class__._sub(self, other)

    def __rsub__(self, other):
        return self.__class__._sub(other, self)

    def __mul__(self, other):
        return self.__class__._mul(self, other)

    def __rmul__(self, other):
        return self.__class__._mul(other, self)

    def __truediv__(self, other):
        return self.__class__._div(self, other)

    def __rtruediv__(self, other):
        return self.__class__._div(other, self)

    def __pow__(self, other):
        return self.__class__._pow(self, other)

    def __rpow__(self, other):
        return self.__class__._pow(other, self)

    def __abs__(self):
        return self.__class__._abs(self)

    def __str__(self):
        return f"S[{self.to_str()}]"

    def __repr__(self):
        return self.to_str()


"""
Note:
=====

Modifier inherits to _Scalar, an abstract base class for scalars.
Modifier can also inherit to any other summable like matrices or other
individual datatypes
"""
